<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Katalog Mochi</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#fffaf7}.hero{background:linear-gradient(135deg,#fff0f5,#f7efff);border-radius:28px}.p-card{border:0;border-radius:20px;box-shadow:0 8px 30px #43204410;overflow:hidden}.p-img{height:210px;object-fit:cover;background:#fff0f5}</style></head><body><nav class="navbar bg-white border-bottom"><div class="container"><a class="navbar-brand fw-bold">🍡 MochiERP</a><a class="btn btn-outline-dark" href="?route=login">Login</a></div></nav><main class="container py-5"><section class="hero p-5 mb-5"><div class="row align-items-center"><div class="col-lg-7"><h1 class="display-5 fw-bold">Mochi lembut untuk setiap momen.</h1><p class="lead text-muted">Katalog produk Mochi Store berbasis database ERP.</p></div><div class="col-lg-5 text-center" style="font-size:7rem">🍡</div></div></section><div class="row g-4"><?php foreach($rows as $p): ?><div class="col-md-6 col-lg-3"><div class="card p-card h-100"><img class="p-img" src="<?=base_url('uploads/'.e($p['gambar']))?>" onerror="this.style.display='none'"><div class="card-body"><div class="small text-muted"><?=e($p['nama_kategori'])?></div><h5 class="fw-bold"><?=e($p['nama_produk'])?></h5><p class="small text-muted"><?=e(mb_strimwidth($p['deskripsi']??'',0,100,'...'))?></p><div class="fw-bold">Rp <?=number_format($p['harga_jual'],0,',','.')?></div></div></div></div><?php endforeach; ?></div></main></body></html>